from .api_base import API_base 

class Nearest_Airport_from_Postal_Code(API_base):
    """
    This API returns the nearest airport to a given postal code and country code. The straight line distance between the postal code and airport is measured, and the result is returned in kilometers.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_postal_code", "p_country_code"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_postal_code = params.get('p_postal_code', None)
        if p_postal_code is None:
            return self.handle_error(f"Required parameter 'p_postal_code' is missing", 400)
        is_valid, error = self.validate_type(p_postal_code, 'p_postal_code', str)
        if not is_valid:
            return error
        
        p_country_code = params.get('p_country_code', None)
        if p_country_code is None:
            return self.handle_error(f"Required parameter 'p_country_code' is missing", 400)
        is_valid, error = self.validate_type(p_country_code, 'p_country_code', str)
        if not is_valid:
            return error
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Nearest_Airport_from_Postal_Code",
                "p_postal_code": p_postal_code,
                "p_country_code": p_country_code
            }
        }

class Earthquakes(API_base):
    """
    Retrieves the 100 most recent earthquakes from all over the world. Optional parameters can be used to filter the results by location, intensity, type, magnitude, and count.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_units", "p_latitude", "p_longitude", "p_radius", "p_intensity", "p_type", "p_magnitude", "p_count", "p_start"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_units = params.get('p_units', "miles")
        if p_units is not None:
            is_valid, error = self.validate_type(p_units, 'p_units', str)
            if not is_valid:
                return error
        
        p_latitude = params.get('p_latitude', "33.962523")
        if p_latitude is not None:
            is_valid, error = self.validate_type(p_latitude, 'p_latitude', str)
            if not is_valid:
                return error
        
        p_longitude = params.get('p_longitude', "-118.3706975")
        if p_longitude is not None:
            is_valid, error = self.validate_type(p_longitude, 'p_longitude', str)
            if not is_valid:
                return error
        
        p_radius = params.get('p_radius', "1000")
        if p_radius is not None:
            is_valid, error = self.validate_type(p_radius, 'p_radius', str)
            if not is_valid:
                return error
        
        p_intensity = params.get('p_intensity', "1")
        if p_intensity is not None:
            is_valid, error = self.validate_type(p_intensity, 'p_intensity', str)
            if not is_valid:
                return error
        
        p_type = params.get('p_type', "earthquake")
        if p_type is not None:
            is_valid, error = self.validate_type(p_type, 'p_type', str)
            if not is_valid:
                return error
        
        p_magnitude = params.get('p_magnitude', "3")
        if p_magnitude is not None:
            is_valid, error = self.validate_type(p_magnitude, 'p_magnitude', str)
            if not is_valid:
                return error
        
        p_count = params.get('p_count', "100")
        if p_count is not None:
            is_valid, error = self.validate_type(p_count, 'p_count', str)
            if not is_valid:
                return error
        
        p_start = params.get('p_start', "1")
        if p_start is not None:
            is_valid, error = self.validate_type(p_start, 'p_start', str)
            if not is_valid:
                return error
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Earthquakes",
                "p_units": p_units,
                "p_latitude": p_latitude,
                "p_longitude": p_longitude,
                "p_radius": p_radius,
                "p_intensity": p_intensity,
                "p_type": p_type,
                "p_magnitude": p_magnitude,
                "p_count": p_count,
                "p_start": p_start
            }
        }

